SELECT i.id, i.last_restock, i.quantity, p.category, p.cost, s.store_name, COALESCE(s.store_name, 'unassigned') AS store_name_filled FROM inventory i INNER JOIN products p ON i.product_id = p.id INNER JOIN stores s ON i.store_id = s.id WHERE i.product_id IN (1, 2, 4, 9) ORDER BY store_name DESC, last_restock;
